package extern

import (
	"fmt"
	"go/types"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"

	"gofx/lexer"
)

// BindOptions describes the language scope receiving generated declarations.
// Float is enabled only when the checker supports the Float builtin. Prelude
// contains existing value names, used to warn about unprefixed collisions.
type BindOptions struct {
	Prefix  string
	Float   bool
	Prelude map[string]bool
	Package string // receiving gofx package; empty selects main
}

// Bind emits a complete gofx file with declarations and deterministic skip
// comments. A prefix retains the Go name's capital letter: str + ToUpper.
func Bind(pkg *Package, options BindOptions) string {
	var out strings.Builder
	command := pkg.Path
	if options.Prefix != "" {
		command += " --prefix " + options.Prefix
	}
	name := options.Package
	if name == "" {
		name = "main"
	}
	fmt.Fprintf(&out, "// Code generated by gofx bind %s. DO NOT EDIT.\npackage %s\n\n", command, name)
	for _, f := range pkg.Functions {
		params, result, reason := bindingTypes(f.Signature, options.Float)
		if reason != "" {
			fmt.Fprintf(&out, "// skipped: %s (%s)\n", f.Name, reason)
			continue
		}
		name := options.Prefix + f.Name
		if options.Prefix == "" {
			r, size := utf8.DecodeRuneInString(f.Name)
			name = string(unicode.ToLower(r)) + f.Name[size:]
			if options.Prelude[name] {
				fmt.Fprintf(&out, "// collides with prelude: %s\n", name)
			}
		}
		tokens, err := lexer.New(name).All()
		first, _ := utf8.DecodeRuneInString(name)
		if err != nil || tokens[0].Kind != lexer.Ident || tokens[0].Text != name ||
			!unicode.IsLower(first) || strings.HasPrefix(name, "ext_") || strings.HasPrefix(name, "dict_") {
			fmt.Fprintf(&out, "// skipped: %s (reserved gofx name %s; use --prefix)\n", f.Name, name)
			continue
		}
		for i, typ := range params {
			params[i] = fmt.Sprintf("p%d %s", i, typ)
		}
		fmt.Fprintf(&out, "extern func %s(%s) %s = %s.%s\n", name, strings.Join(params, ", "), result, strconv.Quote(pkg.Path), f.Name)
	}
	return out.String()
}

func bindingTypes(sig *types.Signature, floats bool) ([]string, string, string) {
	if sig.TypeParams().Len() != 0 {
		return nil, "", "generic function"
	}
	if sig.Variadic() {
		return nil, "", "variadic function"
	}
	params := make([]string, sig.Params().Len())
	for i := range params {
		typ := sig.Params().At(i).Type()
		var ok bool
		params[i], ok = bindingType(typ, floats)
		if !ok {
			return nil, "", fmt.Sprintf("unsupported parameter type %s", types.TypeString(typ, nil))
		}
	}
	results := sig.Results()
	if results.Len() == 0 {
		return nil, "", "no result; Unit requires rt.Unit"
	}
	first := results.At(0).Type()
	result, ok := bindingType(first, floats)
	if !ok {
		return nil, "", fmt.Sprintf("unsupported result type %s", types.TypeString(first, nil))
	}
	switch results.Len() {
	case 1:
		return params, result, ""
	case 2:
		second := results.At(1).Type()
		if types.Identical(second, types.Universe.Lookup("error").Type()) {
			return params, "IO[" + result + "]", ""
		}
		if types.Identical(second, types.Typ[types.Bool]) && (result == "Int" || result == "Float" || result == "String" || result == "Bool" || result == "Unit") {
			return params, "Option[" + result + "]", ""
		}
	}
	return nil, "", "unsupported multiple results"
}

func bindingType(t types.Type, floats bool) (string, bool) {
	for _, entry := range []struct {
		goType types.BasicKind
		gfx    string
	}{
		{types.Int64, "Int"}, {types.Int, "Int"}, {types.String, "String"}, {types.Bool, "Bool"},
	} {
		if types.Identical(t, types.Typ[entry.goType]) {
			return entry.gfx, true
		}
	}
	if floats && types.Identical(t, types.Typ[types.Float64]) {
		return "Float", true
	}
	if types.Identical(t, types.NewSlice(types.Typ[types.String])) {
		return "List[String]", true
	}
	if types.Identical(t, types.NewSlice(types.Typ[types.Int64])) {
		return "List[Int]", true
	}
	if named(t, "gofx/rt", "Unit") {
		return "Unit", true
	}
	// any and rt.IO erase the gofx type (and IO result), so they require an
	// explicit user declaration instead of inventing an unsafe polymorphic API.
	return "", false
}
